   129→/// Register a new market type in the protocol, generally we dont remove markets
   130→public(package) fun add_market<MarketType>(
   131→    self: &mut ProtocolApp,
   132→    id: ID,
   133→) {
   134→    let key = type_name::with_defining_ids<MarketType>();
   135→    assert!(!self.markets.contains(key), error::market_already_exists());
   136→    self.markets.add(key, id);
   137→}
