   139→/// Validate that a market is registered and matches the provided market object
   140→public(package) fun validate_market<MarketType>(self: &ProtocolApp, market: &Market<MarketType>) {
   141→    let market_key = type_name::with_defining_ids<MarketType>();
   142→    assert!(self.markets.contains(market_key), error::market_not_found());
   143→    assert!(self.markets.borrow(market_key) == &object::id(market), error::invalid_market());
   144→}
