   159→public(package) fun ensure_has_permission(self: &ProtocolApp, id: ID, what: u8) {
   160→    let whitelist = dynamic_field::borrow<PackageWhitestKey, VecMap<ID, u32>>(&self.id, PackageWhitestKey {});
   161→
   162→    assert!(whitelist.contains(&id), error::caller_not_whitelisted());
   163→
   164→    let permission = *whitelist.get(&id);
   165→    
   166→    let mask = 1u32 << what;
   167→    let has_permission = (permission & mask) != 0;
   168→
   169→    assert!(has_permission, error::caller_has_no_permission());
   170→}
